(()=>{'use strict';const input=new URLSearchParams(location.search);const keys=['utm_source','utm_medium','utm_campaign','utm_content','utm_term','utm_id','fbclid','gclid','ttclid','xcod','sck','src','src_id'];let saved={};try{saved=JSON.parse(sessionStorage.getItem('almofadas_attribution_v2')||'{}').values||{}}catch{}for(const link of document.querySelectorAll('[data-next],[data-checkout]')){const url=new URL(link.href);for(const key of keys){const v=input.get(key)||saved[key];if(v&&v.length<=1000)url.searchParams.set(key,v)}link.href=url.href}})();